namespace generic.algorithms;

/**
 * A reducing LCS that works on Strings.
 */
public class StringReducingLcs : ReducingLcs<string, Character> {

	public StringReducingLcs(string x, string y) : base(x, y)
    {
	}

	/* @Override */
	protected string reduce(string input, int start, int end) {
		return input.substring(start, end);
	}

	/* @Override */
	protected int lengthOf(string s) {
		return s.length();
	}

	/* @Override */
	protected Character valueOf(string s, int offset) {
		return s.charAt(offset);
	}
}
